import androidx.appcompat.app.AppCompatActivity;
import android.os.Bundle;
import android.view.View;
import android.widget.ImageButton;
import android.widget.Toast;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class MainActivity extends AppCompatActivity {

    private List<Integer> cardImages = Arrays.asList(
            R.drawable.photo1, R.drawable.photo2, R.drawable.photo3, R.drawable.photo4,
            R.drawable.photo1, R.drawable.photo2, R.drawable.photo3, R.drawable.photo4
    );
    private ImageButton[] buttons = new ImageButton[8];
    private int[] cardStates = new int[8];  // 0=hidden, 1=visible, 2=matched
    private int firstCardIndex = -1;
    private int secondCardIndex = -1;
    private int matchedCount = 0;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        Collections.shuffle(cardImages);

        for (int i = 0; i < 8; i++) {
            final int index = i;
            buttons[i] = findViewById(getResources().getIdentifier("card" + (i + 1), "id", getPackageName()));
            buttons[i].setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    if (cardStates[index] == 0 || cardStates[index] == 2) {
                        return;  // Ignore hidden or matched cards
                    }
                    flipCard(index);
                }
            });
        }
    }

    private void flipCard(int index) {
        ImageButton button = buttons[index];
        button.setImageResource(cardImages.get(index));

        if (firstCardIndex == -1) {
            firstCardIndex = index;
        } else {
            secondCardIndex = index;
            checkMatch();
        }
    }

    private void checkMatch() {
        if (cardImages.get(firstCardIndex).equals(cardImages.get(secondCardIndex))) {
            cardStates[firstCardIndex] = 2;
            cardStates[secondCardIndex] = 2;
            matchedCount += 2;
            checkWin();
        } else {
            buttons[firstCardIndex].postDelayed(new Runnable() {
                @Override
                public void run() {
                    buttons[firstCardIndex].setImageResource(R.drawable.photo5);
                    buttons[secondCardIndex].setImageResource(R.drawable.photo5);
                }
            }, 1000);
        }

        firstCardIndex = -1;
        secondCardIndex = -1;
    }

    private void checkWin() {
        if (matchedCount == 8) {
            Toast.makeText(this, "You win!", Toast.LENGTH_SHORT).show();
        }
    }
}

