        for (int i = 0; i < imageButtons.length; i++) {
            indices.add(i);
        }

        Collections.shuffle(indices); // Shuffle the indices randomly

        for (int i = 0; i < imageButtons.length; i++) {
            final int index = i;
            final int randomIndex = indices.get(i);

            imageButtons[randomIndex].setOnClickListener(new View.OnClickListener() {
                @Override
