export async function load3DTileset(mapViewer:Cesium.Viewer, tileUrl:string) {
  const  tileSet = await Cesium.Cesium3DTileset.fromUrl(
      tileUrl, {
    projectTo2D: true,
  })
  mapViewer.scene.primitives.add(tileSet)
  await mapViewer.zoomTo(tileSet)
  return tileSet
}

const tileSet = await Cesium.Cesium3DTileset.fromUrl(tileUrl, {
  projectTo2D: true,
});

mapViewer.scene.primitives.add(tileSet);
await mapViewer.zoomTo(tileSet);

// 隐藏 Cesium3DTileset 对象
tileSet.show = value;

return tileSet;

function checkboxOnclick(value: boolean, tileUrl: string){//根据checkbox中的是否来判断是否加载3DTileset
  var viewer = new Cesium.Viewer('cesiumContainer');
  var tileSet;
  Cesium.Cesium3DTileset.fromUrl(tileUrl, {
    projectTo2D: true,
  }).then(function (loadedTileset) {
    tileSet = loadedTileset;
    viewer.scene.primitives.add(tileSet);
  });
  if (value) {
    // 当checkbox被选中时，添加3D Tileset图层
    Cesium.Cesium3DTileset.fromUrl(tileUrl, { projectTo2D: true }).then(function (loadedTileset) {
      tileSet = loadedTileset;
      viewer.scene.primitives.add(tileSet);
    });
