оптимизируй этот код:
uniform vec2 res;
    uniform sampler2D tex;
    uniform vec3 mouse;
    uniform vec2 mouseReal;
    uniform vec2 variable;
    uniform sampler2D videoTexture;


    vec3 circle(float dist, float radius) {
        if(dist<radius) {
            return vec3(0.0);
        } else {
            return vec3(1.0);
        }
    }
    vec2 movePointOfTime(vec2 randPoint, float variable,float sign) {
        float speed = sign * variable*100.0;
        randPoint.x = sin(speed/100.0)*100.0+randPoint.x+mouse.x-400.0;
        randPoint.y = cos(speed/100.0)*100.0+randPoint.y+mouse.y-400.0;
        return randPoint;
    }

    vec3 createLayers(vec3 color, float distMouse, float distPointResult) {
        color = mix(vec3(0.9,0.5,0.5),vec3(0.12,0.11,0.50),distMouse * distPointResult/800000000000000000000000.0);
        color = mix(vec3(0.9,0.9,1.0),vec3(1.0,1.0,1.0),-color*10000.5);
        return color;
    }

    void main() {
        float pi = 3.1415926535;
        vec2 uv = mod((gl_FragCoord.xy / res.x*5.8)*1.5,20.0);
        uv = mod(uv,1.0);
        vec2 startPoint[9];
        vec2 randPoint[9];
        float distPoint[9];
        vec3 circlePoint[9];

        startPoint[0] = vec2(200.0,200.0);
        startPoint[1] = vec2(400.0,200.0);
        startPoint[2] = vec2(600.0,200.0);
        startPoint[3] = vec2(200.0,400.0);
        startPoint[4] = vec2(400.0,400.0);
        startPoint[5] = vec2(600.0,400.0);
        startPoint[6] = vec2(200.0,600.0);
        startPoint[7] = vec2(400.0,600.0);
        startPoint[8] = vec2(600.0,600.0);

        float radius = 0.0;

        float sign[9];
        sign[0] = -1.0/5.0;
        sign[1] = 1.0;
        sign[2] = -1.0/2.0;
        sign[3] = 1.0;
        sign[4] = -1.0/3.0;
        sign[5] = 1.0;
        sign[6] = -1.0/4.0;
        sign[7] = 1.0;
        sign[8] = -1.0/1.0;

        for(int i = 0; i<9; i++) {
            randPoint[i] = movePointOfTime(startPoint[i],variable.x,sign[i]);
            distPoint[i] = distance(gl_FragCoord.xy,randPoint[i]);
            circlePoint[i] = circle(distPoint[i],radius);
        }
        float distMouse = distance(gl_FragCoord.xy,mouse.xy);
        float distMouseReal = distance(gl_FragCoord.xy,mouseReal.xy);
        vec3 circleMouse = circle(distMouse,radius);
        vec3 circleMouseReal = circle(distMouseReal,radius);
        vec3 circlePointResult = circlePoint[0] * circlePoint[1] * circlePoint[2] * circlePoint[3] * circlePoint[4] * circlePoint[5] * circlePoint[6] * circlePoint[7] * circlePoint[8];
        float distPointResult = distPoint[0] * distPoint[1] * distPoint[2] * distPoint[3] * distPoint[4] * distPoint[5] * distPoint[6] * distPoint[7] * distPoint[8];
        vec3 color = circleMouse * circleMouseReal * circlePointResult;

        if(color == vec3(1.0)) {
            color = createLayers(color, distMouseReal, distPointResult);
            //color = mix(vec3(1.0), texture2D(videoTexture, uv).rgb,color);
        }
        if(color.r < 1.0) {
            color = texture2D(videoTexture, uv).rgb;
            //color =  mod(vec3(0.4,uv.x,0.5),0.1)*uv.x*8.0;
        } else {
            color = 0.7 - color;
        }
        gl_FragColor = vec4(color,1.0);
    }

