import React from 'react';

import { yupResolver } from '@hookform/resolvers/yup';
import { Edit as EditIcon, Refresh as RefreshIcon } from '@mui/icons-material';
import {
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from '@mui/material';
import cx from 'classnames';
import { useForm } from 'react-hook-form';
import { useTranslation } from 'react-i18next';
import { useLocation } from 'react-router-dom';

import {
  Button,
  Divider,
  ErrorState,
  Loader,
  MultiSelect,
} from 'components/common';
import {
  ConfirmRiskSettingsOverrideModal,
  MarketCardRiskSettingsForm,
  StateCardOverrideEvent,
} from 'components/manualActions';
import { STATE_SELECTOR_CONFIG } from 'constants/MultiSelect';
import { table } from 'constants/Tables';
import {
  initialFormValuesRiskSettings,
  useManualActionsContext,
} from 'contexts/ManualActionsContext';
import { usePermissionsContext } from 'contexts/PermissionsContext';
import { BranchStatus } from 'models/BranchStatus';
import { RiskSettingsEventLevelPayload } from 'models/ManualActions';
import {
  RiskSettingsFormValues,
  RiskSettingsType,
} from 'models/RiskSettingsForm';
import { SportingEvent } from 'models/SportingEvent';
import { State } from 'models/State';
import { TableHeader } from 'models/Table';
import { buildRSEventPayload, hasErrors } from 'utils/ManualActions';
import { riskSettingsFormSchema } from 'utils/Schema';

export interface EventCardProps {
  states: State[];
  loading?: boolean;
  error?: boolean;
  event: SportingEvent;
  onEditMarketsClick: () => void;
  onGetEvent: () => void;
}

export const EventCardOverride: React.FC<EventCardProps> = ({
  states,
  loading,
  error,
  event,
  onEditMarketsClick,
  onGetEvent,
}) => {
  const { t } = useTranslation();
  const { isAdminUser } = usePermissionsContext();

  const {
    expandedEventOverrideStates,
    setExpandedEventOverrideStates,
    overrideEventRS,
    overrideEventRSStatus,
    setOverrideEventRSStatus,
  } = useManualActionsContext();

  const [isModalOpen, setIsModalOpen] = React.useState(false);
  const [payload, setPayload] = React.useState<RiskSettingsEventLevelPayload>();
  const [selectedStates, setSelectedStates] = React.useState<string[]>(
    states.map((state) => state.id),
  );

  const {
    control,
    handleSubmit,
    errors,
    setValue,
    watch,
    trigger,
    formState: { isSubmitted, isDirty },
  } = useForm<RiskSettingsFormValues>({
    resolver: yupResolver(
      riskSettingsFormSchema(t, RiskSettingsType.EVENT, false, true),
    ),
  });

  const refreshIconStyles = cx('market-card__icon-button--refresh');
  const eventCardStyles = cx('market-card market-card--risk-settings', {
    loading,
    error,
  });
  const eventCardInnerStyles = cx('market-card__inner', { loading, error });

  const tableHeaders: TableHeader[] = table.riskSettingsTable(t);

  const onOverride = async (data: RiskSettingsFormValues) => {
    setIsModalOpen(true);
    setPayload(buildRSEventPayload(data, data.states || selectedStates));
  };

  const onSuccess = () => setIsModalOpen(false);
  const onFailure = () => setOverrideEventRSStatus(BranchStatus.IDLE);

  const onConfirmOverride = async () => {
    await overrideEventRS(
      onSuccess,
      onFailure,
      event?.id as string,
      payload as RiskSettingsEventLevelPayload,
    );
    setOverrideEventRSStatus(BranchStatus.IDLE);
  };

  // Enable the beforeunload event when certain conditions are met
  React.useEffect(() => {
    return () => {
      console.log('hey');
    };
  }, [isDirty]);

  return (
    <>
      {overrideEventRSStatus !== BranchStatus.FINISHED && (
        <ConfirmRiskSettingsOverrideModal
          selectedStates={payload ? payload.instances : ['']}
          states={states}
          event={event}
          type={RiskSettingsType.EVENT}
          open={isModalOpen}
          onClose={() => {
            setIsModalOpen(false);
          }}
          eventName={event?.name}
          onConfirm={() => onConfirmOverride()}
          isLoading={overrideEventRSStatus === BranchStatus.LOADING}
        />
      )}
      <div className={eventCardStyles} data-testid="event-card">
        <div className={eventCardInnerStyles}>
          <form
            className="market-card__form"
            onSubmit={handleSubmit(onOverride)}
            data-testid="market-card-form"
          >
            <div className="market-card__header">
              <h2 className="market-card__form-header">
                {t('pages.manualActions.event')}
              </h2>
              <div className="market-card__header-buttons">
                <Button
                  testId="edit-markets-button"
                  buttonColor="default"
                  variant="outlined"
                  className="market-card__edit-selections-button"
                  onClick={onEditMarketsClick}
                >
                  <span className="page__icon-button-content">
                    <EditIcon />
                    {t('common.cta.editMarkets')}
                  </span>
                </Button>
                <Divider className="market-card__divider" />
                <IconButton
                  size="large"
                  data-testid="event-card-refresh-button"
                  className={refreshIconStyles}
                  onClick={onGetEvent}
                  aria-label={t('accessibility.refresh')}
                >
                  <RefreshIcon />
                </IconButton>
              </div>
            </div>
            <div className="market-card__header-controls">
              <div>
                <MultiSelect
                  className="state-selector"
                  label={t('form.states')}
                  options={states.map((state) => {
                    return { label: state.name, value: state.id };
                  })}
                  testId={`market-card-state-selector`}
                  onChange={setSelectedStates}
                  value={selectedStates}
                  hasSelectAll
                  selectAllConfig={STATE_SELECTOR_CONFIG}
                  required
                />
              </div>
              <Button
                testId="event-card-override-button"
                buttonColor="positive"
                type="submit"
                disabled={
                  !isAdminUser || hasErrors(errors) || !selectedStates.length
                }
              >
                {t('common.cta.override')}
              </Button>
            </div>
            <div className="market-card__content">
              <MarketCardRiskSettingsForm
                control={control}
                errors={errors}
                mgltl={false}
                defaultValues={initialFormValuesRiskSettings}
                differentialLimits={true}
                type={RiskSettingsType.EVENT}
                testId="event-card-form"
                setValue={setValue}
                watch={watch}
                isSubmitted={isSubmitted}
                trigger={trigger}
              />
            </div>
          </form>
          <TableContainer
            data-testid="state-table"
            className="table table--risk-settings"
          >
            <Table>
              <TableHead>
                <TableRow>
                  {tableHeaders.map((header, index) => (
                    <TableCell
                      key={`state-header-${index}`}
                      align={header.alignment ?? 'left'}
                    >
                      <p className="xs">{header.title}</p>
                    </TableCell>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {states.map((state, index) => (
                  <StateCardOverrideEvent
                    key={index}
                    index={index}
                    state={state}
                    expandedRows={expandedEventOverrideStates}
                    setExpandedRows={setExpandedEventOverrideStates}
                    onOverride={(stateData) => onOverride(stateData)}
                    event={event}
                  />
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </div>
        {loading && <Loader testId={`event-card-loading`} />}
        {error && !loading && <ErrorState onRetry={onGetEvent} />}
      </div>
    </>
  );
};
