export const getInitCollectedCombo = (
  comboGroups: ComboEditorCtxProps['comboGroups'],
  products: ComboEditorCtxProps['products'],
) => (
  comboGroups.reduce((acc, comboGroup) => {
    if (comboGroup.required || !comboGroup.parentId) {
      const firstAvailableProduct = comboGroup.items.find((itemId) => !products[itemId].stopped);
      acc[comboGroup.id] = firstAvailableProduct || comboGroup.items[0] || null;
    } else {
      acc[comboGroup.id] = null;
    }
    return acc;
  }, {} as Record<number, number | null>)
);

