export async function SSHConnect(agent: AgentList, agentName: Project | string, os: Platform): Promise<void> {
  if (os === Platform.Windows) {
    await ssh.connect({
      host: agent.ip,
      username: agentName,
      port: 22,
      password: SSHUser.Password,
      readyTimeout: 15000,
    });
  } else if (os === Platform.Linux) {
    await ssh.connect({
      host: agent.ip,
      username: agentName,
      port: 22,
      privateKeyPath: SSH.PrivateKeyPath,
      readyTimeout: 15000,
    });
  }
}

export async function SSHDisconnect(agent: AgentList, agentName: Project, os: Platform): Promise<void> {
  if (os === Platform.Linux) {
    await SSHConnect(agent, agentName, os).then(() => ssh.dispose());
  } else if (os === Platform.Windows) {
    await SSHConnect(agent, agentName, os);
  }
}

export async function SSHIncorrect(agent: AgentList, agentName: string, os: Platform): Promise<void> {
  try {
    await SSHConnect(agent, agentName, os);
  } catch (error) {
    console.log(error);
  }
}

export async function logonTest(options: LogonOptions): Promise<void> {
  await OperationRepeater.RepeatUntil(
    async () => (await clickHouseService.getLogon(options.agent.name, options.username, options.outcome)).length !== 0,
    40,
    1,
  );

  const logon = await clickHouseService.getLogon(options.agent.name, options.username, options.outcome);
  expect(logon.length > 0, `length 1 < ${logon.length} username: ${options.username}`).toBeTruthy();
  baseExpect(logon, options.os);
  expect(logon[0].hostId, 'hostId').toEqual(options.agent.id);
  expect(logon[0].outcome, 'outcome').toEqual(options.outcome);
  if (options.os === Platform.Linux) {
    expect(logon[0].dstacc, 'dstacc').toEqual(options.username);
  }
}

export async function logoffTest(options: LogoffOptions): Promise<void> {
  await OperationRepeater.RepeatUntil(async () => (await clickHouseService.getLogoff(options.agent.name, options.username)).length !== 0, 40, 1);

  const logoff = await clickHouseService.getLogoff(options.agent.name, options.username);
  expect(logoff.length > 0, `length 1 < ${logoff.length} username: ${options.username}`).toBeTruthy();
  baseExpect(logoff, options.os);
  if (options.os === Platform.Linux) {
    expect(logoff[0].srcacc, 'srcacc').toEqual(options.username);
  }
}

function baseExpect(response: Logoff[] | Logon[], os: Platform): void {
  expect(response[0], 'at').toEqual(Project.Rpoint);
  expect(response[0].logSource, 'logSource').toEqual(os);
  expect(response[0].logonType !== '', 'logonType').toBeTruthy();
}

interface LogonOptions extends LogoffOptions {
  outcome: AgentLogonOutcome;
}

interface LogoffOptions {
  agent: AgentList;
  username: string;
  os: Platform;
}

