const GameBase = artifacts.require("GameBase.sol");
const Penduel = artifacts.require("Penduel.sol");
const PlayerManagement = artifacts.require("PlayerManagement");
const { BN, expectRevert, expectEvent } = require('@openzeppelin/test-helpers');
const { expect } = require('chai');
const { GameStatus } = artifacts.require("GameBase.sol"); 

contract("GameBase", accounts => {

    let gameBaseInstance;
    let penduelInstance;
    let playerManagementInstance;
    let playerManagementAddress;

    const _owner = accounts[0];
    const player1 = accounts[1];
    const player2 = accounts[2];

        describe ("vérifie si chaque valeur de l’énumération GameStatus correspond à la valeur de chaîne de caractères attendue", () => {

            beforeEach(async function() {
                gameBaseInstance = await GameBase.new();
            });

            it("should have 'waitingForPlayers' as the first value in GameStatus", async () => {
                const firstValue = await GameBase.GameStatus.waitingForPlayers();
                expect(firstValue.toString()).to.be.equal("waitingForPlayers");
            });

            it("should have 'waitingForRandomWord' as the second value in GameStatus", async () => {
                const secondValue = await gameBaseInstance.GameStatus.waitingForRandomWord();
                expect(secondValue).to.be.equal("waitingForRandomWord");
            });

            it("should have 'inProgress' as the third value in GameStatus", async () => {
                const thirdValue = await gameBaseInstance.GameStatus.inProgress();
                expect(thirdValue).to.be.equal("inProgress");
            });

            it("should have 'finished' as the fourth value in GameStatus", async () => {
                const fourthValue = await gameBaseInstance.GameStatus.finished();
                expect(fourthValue).to.be.equal("finished");
            });

            it("should have 'cancelled' as the fifth value in GameStatus", async () => {
                const fifthValue = await gameBaseInstance.GameStatus.cancelled();
                expect(fifthValue).to.be.equal("cancelled");
            });
        });

        describe ("vérifie si chaque mapping renvoie une valeur attendue", () => {
        //vérifier si les valeurs sont correctement stockées et récupérées à partir des mappings

            it("should store and retrieve values correctly in mappings", async () => {
                // Créer une instance de contrat GameBase
                const gameBaseInstance = await GameBase.new({ from: _owner });

                // Définir des valeurs dans les mappings
                const gameId = 1;
                const requestId = 123;
                const gameLetter = "A";
                const gameWord = "Hello";
                const playerMove = 0;
                const playerAddress = accounts[3];
                const potValue = 100;
                const balanceWithdrawn = 50;

                gameBaseInstance.games[gameId].status = GameStatus.waitingForRandomWord;
                gameBaseInstance.gameRequestIds[requestId] = gameId;
                gameBaseInstance.gameLetters[playerAddress][gameId] = gameLetter;
                gameBaseInstance.gameWords[playerAddress][gameId] = gameWord;
                gameBaseInstance.gamePlayerMoves[gameId][playerMove] = playerAddress;
                gameBaseInstance.gameBets[gameId][playerAddress].pot = potValue;
                gameBaseInstance.gameBalances[gameId][playerAddress] = balanceWithdrawn;

                const gameStatus = await gameBaseInstance.games[gameId].status;
                const retrievedRequestId = await gameBaseInstance.gameRequestIds[requestId];
                const retrievedGameLetter = await gameBaseInstance.gameLetters[playerAddress][gameId];
                const retrievedGameWord = await gameBaseInstance.gameWords[playerAddress][gameId];
                const retrievedPlayerMove = await gameBaseInstance.gamePlayerMoves[gameId][playerMove];
                const retrievedPotValue = await gameBaseInstance.gameBets[gameId][playerAddress].pot;
                const retrievedBalanceWithdrawn = await gameBaseInstance.gameBalances[gameId][playerAddress];

                expect(gameStatus).to.be.equal(GameStatus.waitingForRandomWord);
                expect(retrievedRequestId).to.be.equal(gameId);
                expect(retrievedGameLetter).to.be.equal(gameLetter);
                expect(retrievedGameWord).to.be.equal(gameWord);
                expect(retrievedPlayerMove).to.be.equal(playerAddress);
                expect(retrievedPotValue).to.be.bignumber.equal(new BN(potValue));
                expect(retrievedBalanceWithdrawn).to.be.bignumber.equal(new BN(balanceWithdrawn));
            });
        });

        beforeEach(async function() {
                gameBaseInstance = await GameBase.new({ from: _owner });
                playerManagementAddress = "0xE7FC27ab56E9F651e0E9A8383F92Ca68Cd9C2f03";
                playerManagementInstance = await PlayerManagement.new({ from: _owner });
                penduelInstance = await Penduel.new(playerManagementAddress, { from: _owner });

        });

        describe("Vérifie l'event Game Created", () => {

            it("should emit GameCreated event", async () => {
                const player1 = accounts[1];
                const player2 = accounts[2];
                const gameId = 1;
                const tx = await playerManagementInstance.createGame(player1, player2, { from: player1 });

                expectEvent(tx, "GameCreated", {
                    _gameId: new BN(gameId),
                    _player1: player1,
                    _player2: player2
                });
            });
        });

        describe("Vérifie l'event Game Joined", () => {

            it("should emit GameJoined event", async () => {
                const player1 = accounts[1];
                const player2 = accounts[2];
                const gameId = 1;
                const tx = await playerManagementInstance.joinGame(gameId, { from: player2 });

                expectEvent(tx, "GameJoined", {
                    _gameId: new BN(gameId),
                    _player2: player2,
                    _player1: player1
                });
            });
        });

        describe("Vérifie l'event Game Started", () => {

            it("should emit GameStarted event", async () => {
                const gameId = 1;
                const player1 = accounts[1];
                const player2 = accounts[2];
                const wordLength = 8;
                const tx = await penduelInstance.startGame(gameId, player1, player2, wordLength, { from: player1 });

                expectEvent(tx, "GameStarted", {
                    _gameId: new BN(gameId),
                    _player1: player1,
                    _player2: player2,
                    _wordLength: new BN(wordLength)
                });
            });
        });

        describe("Vérifie l'event Game Ended", () => {

            it("should emit GameEnded event", async () => {
