                expectEvent(tx, "GameCancelled", {
                    _gameId: new BN(gameId),
                    _player1: player1,
                    _player2: player2
                });
            });
        });

        describe("Vérifie l'event Game Status Updated", () => {

            it("should emit GameStatusUpdated event", async () => {
                const gameId = 1;
                const newStatus = 2; // Nouveau statut du jeu
                const tx = await playerManagementInstance.updatePlayer2(gameId, newStatus, { from: player1 });

