        describe("Vérifie l'event RequestId", () => {

            it("should emit RequestId event", async () => {
                const requestId = "0x1234567890abcdef"; // Valeur du requestId retourné
                const tx = await penduelInstance.requestRandomWords({ from: player1 });

                expectEvent(tx, "RequestId", {
                    requestId: requestId
                });
            });
